export function render(container: HTMLElement) {
  container.innerHTML = `
    <div class="calculator">
      <div class="display" id="display">0</div>
      <div class="buttons">
        <button class="btn" onclick="appendNumber('7')">7</button>
        <button class="btn" onclick="appendNumber('8')">8</button>
        <button class="btn" onclick="appendNumber('9')">9</button>
        <button class="btn" onclick="performOperation('/')">÷</button>
        <button class="btn" onclick="appendNumber('4')">4</button>
        <button class="btn" onclick="appendNumber('5')">5</button>
        <button class="btn" onclick="appendNumber('6')">6</button>
        <button class="btn" onclick="performOperation('*')">*</button>
        <button class="btn" onclick="appendNumber('1')">1</button>
        <button class="btn" onclick="appendNumber('2')">2</button>
        <button class="btn" onclick="appendNumber('3')">3</button>
        <button class="btn" onclick="performOperation('-')">-</button>
        <button class="btn" onclick="appendNumber('0')">0</button>
        <button class="btn" onclick="appendNumber('.')">.</button>
        <button class="btn" onclick="clearDisplay()">C</button>
        <button class="btn" onclick="performOperation('+')">+</button>
        <button class="btn" onclick="calculateResult()">=</button>
      </div>
    </div>
  `;

  let currentInput = '';
  let firstOperand = null;
  let operation = null;

  function appendNumber(num: string) {
    if (currentInput === '0' && num === '0') return;
    currentInput += num;
    updateDisplay();
  }

  function performOperation(op: string) {
    if (currentInput === '') return;
    if (firstOperand !== null) {
      calculateResult();
    }
    firstOperand = parseFloat(currentInput);
    operation = op;
    currentInput = '';
  }

  function clearDisplay() {
    currentInput = '';
    firstOperand = null;
    operation = null;
    updateDisplay();
  }

  function calculateResult() {
    if (currentInput === '' || firstOperand === null || operation === null) return;
    const secondOperand = parseFloat(currentInput);
    let result = 0;
    switch (operation) {
      case '+':
        result = firstOperand + secondOperand;
        break;
      case '-':
        result = firstOperand - secondOperand;
        break;
      case '*':
        result = firstOperand * secondOperand;
        break;
      case '/':
        if (secondOperand === 0) {
          currentInput = 'Error';
          updateDisplay();
          return;
        }
        result = firstOperand / secondOperand;
        break;
    }
    currentInput = result.toString();
    firstOperand = null;
    operation = null;
    updateDisplay();
  }

  function updateDisplay() {
    const display = container.querySelector('#display') as HTMLElement;
    if (display) {
      display.textContent = currentInput;
    }
  }
}
